mapper.insert:
insert into iip_points_monthly_quota (
    rule_id, member_id, quota_month, awarded_points, create_time, update_time
) values (
    #{ruleId}, #{memberId}, #{quotaMonth}, 0, sysdate(), sysdate()
)
on duplicate key update update_time = update_time

mapper.select:
select awarded_points
from iip_points_monthly_quota
where rule_id = #{ruleId}
  and member_id = #{memberId}
  and quota_month = #{quotaMonth}
for update

mapper.update:
update iip_points_monthly_quota
set awarded_points = awarded_points + #{points},
    update_time = sysdate()
where rule_id = #{ruleId}
  and member_id = #{memberId}
  and quota_month = #{quotaMonth}
